import sys

def main():
    data = sys.stdin.read().split()
    if len(data) < 3:
        return
    a = int(data[0])
    b = int(data[1])
    op = data[2]

    if op == '+':
        print(a + b)
    elif op == '-':
        print(a - b)
    elif op == '*':
        print(a * b)
    elif op == '/':
        print(a // b)

if __name__ == "__main__":
    main()
